diff --git a/packages/workflow/test/native-evaluation-vm2-nodes.test.ts b/packages/workflow/test/native-evaluation-vm2-nodes.test.ts
new file mode 100644
index 000000000..f44851b96
--- /dev/null
+++ b/packages/workflow/test/native-evaluation-vm2-nodes.test.ts
@@ -0,0 +1,71 @@
+import type { MockInstance } from 'vitest';
+
+import { nodeTypes } from './ExpressionExtensions/helpers';
+import { Expression } from '../src/expression';
+import type { INode } from '../src/interfaces';
+import { Workflow } from '../src/workflow';
+
+const node = (name: string, type: string): INode => ({
+	name,
+	type,
+	typeVersion: 1,
+	id: name,
+	position: [0, 0],
+	parameters: {},
+});
+
+const build = (...extra: INode[]) =>
+	new Workflow({
+		nodes: [node('node', 'test.set'), ...extra],
+		connections: {},
+		active: false,
+		nodeTypes,
+	});
+
+describe('Expression - native evaluation with vm2 sandbox nodes', () => {
+	let evaluateNative: MockInstance;
+
+	beforeEach(() => {
+		evaluateNative = vi.spyOn(
+			Expression as unknown as { evaluateNative: () => unknown },
+			'evaluateNative',
+		);
+		Expression.setNativeEvaluation(true);
+	});
+
+	afterEach(() => {
+		Expression.setNativeEvaluation(false);
+		evaluateNative.mockRestore();
+	});
+
+	const evaluate = async (wf: Workflow) => {
+		await wf.expression.acquireIsolate();
+		try {
+			return wf.expression.getParameterValue(
+				'={{ $json.name }}',
+				null,
+				0,
+				0,
+				'node',
+				[{ json: { name: 'a' } }],
+				'manual',
+				{},
+			);
+		} finally {
+			await wf.expression.releaseIsolate();
+		}
+	};
+
+	test('evaluates natively without sandbox nodes', async () => {
+		expect(await evaluate(build())).toBe('a');
+		expect(evaluateNative).toHaveBeenCalledTimes(1);
+	});
+
+	test.each(['n8n-nodes-base.function', 'n8n-nodes-base.functionItem'])(
+		'skips native evaluation when the workflow has a %s node',
+		async (type) => {
+			expect(await evaluate(build(node('sandbox', type)))).toBe('a');
+			expect(evaluateNative).not.toHaveBeenCalled();
+		},
+	);
+});
